# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe TimekeepingLocalOwnerSpecHelpers do
  # "Move the shared count, row_counts and ownership setup into one spec/support helper."
  let(:company) { create(:company) }
  let(:project) { create(:project, client: create(:client, company:)) }

  def create_entry_through_owner(user, key)
    Timekeeping::LocalOwner.call(
      operation: :create, company_id: company.id, generation: TimekeepingOwnership.current.generation.to_s,
      actor: Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "employee"),
      params: {
        "idempotency_key" => key,
        "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 30.0,
                    "note" => "counted", "source" => "manual", "source_metadata" => {} }
      }
    )
  end

  def seed_local_entry(user)
    Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 15.0, bill_status: TimesheetEntry.bill_statuses.keys.find { |status| status != "billed" }
    )
  end

  # A refused write that still leaves a row in any one of these tables must show up as a
  # changed count; a default table list that drops one would let that leak pass silently.
  it "timekeeping_row_counts counts every written table by default and sees a write in each" do
    prepare_local_ownership!
    user = timekeeping_member(company, "employee")
    before = timekeeping_row_counts

    expect(TIMEKEEPING_WRITE_TABLES).to contain_exactly("entries", "entry_audits", "idempotency_records", "entry_outbox_items")
    expect(before.keys).to contain_exactly("entries", "entry_audits", "idempotency_records", "entry_outbox_items")
    expect(before.values).to all(eq(0))

    expect(create_entry_through_owner(user, "row-counts-helper-key").status).to eq(201)
    after_first = timekeeping_row_counts
    expect(after_first).to eq(
      "entries" => 1, "entry_audits" => 1, "idempotency_records" => 1, "entry_outbox_items" => 1
    )

    seed_local_entry(user)
    after_seed = timekeeping_row_counts
    expect(after_seed.values).to all(be_an(Integer))
    expect(after_seed["entries"]).to eq(after_first["entries"] + 1)
    expect(after_seed.except("entries")).to eq(after_first.except("entries"))
  end

  it "timekeeping_row_counts counts only the tables it is given, in the order given" do
    seed_local_entry(timekeeping_member(company, "employee"))

    expect(timekeeping_row_counts(%w[entries entry_outbox_items])).to eq("entries" => 1, "entry_outbox_items" => 0)
    counts = timekeeping_row_counts(%w[entry_audits entry_outbox_items])
    expect(counts.keys).to eq(%w[entry_audits entry_outbox_items])
    expect(counts["entry_outbox_items"]).to eq(Timekeeping::LocalOutboxEntry.count)
  end

  # Examples run in any order, so the shared setup must undo a handoff step an earlier
  # arrangement left set; otherwise every write is refused as stale_generation.
  it "prepare_local_ownership! clears a handoff step, stores prepared monolith ownership and keeps the generation" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: "close_admission")
    user = timekeeping_member(company, "employee")

    refused = create_entry_through_owner(user, "during-handoff")
    expect(refused.status).to eq(409)
    expect(refused.body.with_indifferent_access[:reason]).to eq("stale_generation")

    ownership = prepare_local_ownership!

    stored = TimekeepingOwnership.find_by(id: TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to eq(stored)
    expect(ownership).to eq(TimekeepingOwnership.current)
    expect(stored.owner).to eq("monolith")
    expect(stored.monolith_store).to eq("prepared")
    expect(stored.handoff_step).to be_nil
    expect(Timekeeping::EntryOwner.for(stored)).to eq(:prepared)
    expect(create_entry_through_owner(user, "after-prepare").status).to eq(201)

    generation = stored.generation
    prepare_local_ownership!
    expect(TimekeepingOwnership.find_by(id: TimekeepingOwnership::SINGLETON_ID).generation).to eq(generation)
  end

  # The foreign-id example needs one user who holds the same role in both companies,
  # so the foreign entry differs from the caller only in company.
  it "timekeeping_member employs a user with the role and gives one user the same role in two companies when passed" do
    company_a = create(:company)
    company_b = create(:company)

    owner = timekeeping_member(company_a, "owner")
    same_owner = timekeeping_member(company_b, "owner", user: owner)
    other = timekeeping_member(company_a, "employee")

    expect(same_owner.id).to eq(owner.id)
    expect(other).not_to eq(owner)
    expect(Employment.where(user_id: owner.id).pluck(:company_id)).to contain_exactly(company_a.id, company_b.id)
    expect(owner.reload.has_role?("owner", company_a)).to be(true)
    expect(owner.has_role?("owner", company_b)).to be(true)
    expect(owner.has_role?("employee", company_a)).to be(false)
    expect(other.has_role?("employee", company_a)).to be(true)
    expect(other.has_role?("owner", company_a)).to be(false)
  end
end
